  "CONTROL_DATA.warningLights[18].actions[1]": "Do not use any other liquid as a substitute",
  "CONTROL_DATA.warningLights[18].actions[2]": "After refilling the fault lamp normally goes out after driving some distance",
  "CONTROL_DATA.warningLights[18].note": "Fitted to diesel models with SCR only.",
  "CONTROL_DATA.warningLights[19].name": "Low fuel level warning",
  "CONTROL_DATA.warningLights[19].meaning": "The fuel is nearly exhausted.",
  "CONTROL_DATA.warningLights[19].canDrive": "Refuel as soon as possible",
  "CONTROL_DATA.warningLights[19].causes[0]": "Low fuel level (normal indication)",
  "CONTROL_DATA.warningLights[19].causes[1]": "Fuel level sensor failure (warning even after filling up)",
  "CONTROL_DATA.warningLights[19].actions[0]": "Refuel as soon as possible",
  "CONTROL_DATA.warningLights[19].actions[1]": "Do not drive with a permanently low fuel level — the fuel pump is cooled by the fuel, and a low level over a long period shortens its life",
  "CONTROL_DATA.warningLights[20].name": "48 V mild hybrid system warning",
  "CONTROL_DATA.warningLights[20].meaning": "The 48 V mild hybrid system (ISG or BSG) has a fault, which may cause the start/stop function to fail, power to be limited or even prevent the engine from starting.",
  "CONTROL_DATA.warningLights[20].canDrive": "Have it checked soon",
  "CONTROL_DATA.warningLights[20].causes[0]": "48 V battery aged or faulty",
  "CONTROL_DATA.warningLights[20].causes[1]": "ISG motor or DC/DC converter failure",
  "CONTROL_DATA.warningLights[20].causes[2]": "System software problem",
  "CONTROL_DATA.warningLights[20].causes[3]": "Abnormal 12 V battery voltage dragging down the 48 V system",
  "CONTROL_DATA.warningLights[20].actions[0]": "Stop safely, restart once and see whether the message disappears",
  "CONTROL_DATA.warningLights[20].actions[1]": "If the warning persists, avoid long journeys and have the 48 V system fault codes read at a workshop as soon as possible",
  "CONTROL_DATA.warningLights[20].actions[2]": "Do not disconnect the power or remove 48 V components yourself (risk of high voltage and high current)",
  "CONTROL_DATA.warningLights[20].note": "Price source: headline of an article on Youjia (full text could not be retrieved): a 4S dealer initially quoted CNY 15,000–28,000, while a specialist may charge only CNY 100–300, the difference lying mainly in fault-finding ability. Fitted from the W205 facelift (M264) and on the W206 (M254); the belt-driven BSG on early 2019–2021 cars has a relatively high failure rate.",
  "CONTROL_DATA.warningLights[21].name": "Active Brake Assist unavailable",
  "CONTROL_DATA.warningLights[21].meaning": "The radar or camera for the collision warning / automatic emergency braking is obscured or faulty, so the active safety function is temporarily unavailable.",
  "CONTROL_DATA.warningLights[21].canDrive": "You may drive, but the active safety function is unavailable",
  "CONTROL_DATA.warningLights[21].causes[0]": "Mud or snow obscuring the camera area of the windscreen or the radar in the front bumper",
  "CONTROL_DATA.warningLights[21].causes[1]": "Sensor failure",
  "CONTROL_DATA.warningLights[21].causes[2]": "Bad weather (heavy rain, heavy snow, thick fog)",
  "CONTROL_DATA.warningLights[21].causes[3]": "System software fault",
  "CONTROL_DATA.warningLights[21].actions[0]": "First clean the windscreen camera area and the surface of the front bumper radar",
  "CONTROL_DATA.warningLights[21].actions[1]": "Restart the car and see whether it recovers",
  "CONTROL_DATA.warningLights[21].actions[2]": "If the warning persists, the sensor needs calibration or replacement at a workshop",
  "CONTROL_DATA.warningLights[21].note": "After replacing the windscreen the camera must be recalibrated, otherwise the function stays unavailable.",
  "CONTROL_DATA.warningLights[22].name": "Lane Keeping Assist unavailable",
  "CONTROL_DATA.warningLights[22].meaning": "Lane Keeping Assist is temporarily unavailable or has been switched off. This is a \"function restricted\" message, not a \"component failed\" one.",
  "CONTROL_DATA.warningLights[22].canDrive": "You may continue driving",
  "CONTROL_DATA.warningLights[22].causes[0]": "Camera view obstructed (dirt, rain or snow, low sun, night)",
  "CONTROL_DATA.warningLights[22].causes[1]": "Lane markings unclear or a roadworks section",
  "CONTROL_DATA.warningLights[22].causes[2]": "The system has been switched off manually",
  "CONTROL_DATA.warningLights[22].causes[3]": "Camera or steering system calibration lost, abnormal voltage",
  "CONTROL_DATA.warningLights[22].actions[0]": "First clean the windscreen camera area",
  "CONTROL_DATA.warningLights[22].actions[1]": "Make sure you are driving on a road with clear lane markings and check whether the system was switched off manually",
  "CONTROL_DATA.warningLights[22].actions[2]": "The function returns by itself once conditions are met again; if the message persists, have the camera checked and calibrated at a workshop",
  "CONTROL_DATA.warningLights[22].note": "Mercedes temporarily deactivates the function automatically when conditions are not met — this is by design, and it returns by itself once conditions are met, so there is no need to rush to a workshop.",
  "CONTROL_DATA.warningLights[23].name": "Blind Spot Assist unavailable",
